DROP TABLE IF EXISTS `wp_nf3_objects`;
CREATE TABLE `wp_nf3_objects` (
  `id` int NOT NULL AUTO_INCREMENT,
  `type` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci,
