('10768', '2465', '_wp_attachment_metadata', 'a:6:{s:5:\"width\";i:690;s:6:\"height\";i:396;s:4:\"file\";s:33:\"2026/06/INDIANA-UNIVERSITY-2.webp\";s:8:\"filesize\";i:162633;s:5:\"sizes\";a:2:{s:6:\"medium\";a:5:{s:4:\"file\";s:33:\"INDIANA-UNIVERSITY-2-300x172.webp\";s:5:\"width\";i:300;s:6:\"height\";i:172;s:9:\"mime-type\";s:10:\"image/webp\";s:8:\"filesize\";i:44461;}s:9:\"thumbnail\";a:5:{s:4:\"file\";s:33:\"INDIANA-UNIVERSITY-2-150x150.webp\";s:5:\"width\";i:150;s:6:\"height\";i:150;s:9:\"mime-type\";s:10:\"image/webp\";s:8:\"filesize\";i:22843;}}s:10:\"image_meta\";a:12:{s:8:\"aperture\";s:1:\"0\";s:6:\"credit\";s:0:\"\";s:6:\"camera\";s:0:\"\";s:7:\"caption\";s:0:\"\";s:17:\"created_timestamp\";s:1:\"0\";s:9:\"copyright\";s:0:\"\";s:12:\"focal_length\";s:1:\"0\";s:3:\"iso\";s:1:\"0\";s:13:\"shutter_speed\";s:1:\"0\";s:5:\"title\";s:0:\"\";s:11:\"orientation\";s:1:\"0\";s:8:\"keywords\";a:0:{}}}'),
