ield_6977a42478dd2\",\"items_1_link\":\"\",\"_items_1_link\":\"field_6977a42d78dd3\",\"items_2_tag\":\"\",\"_items_2_tag\":\"field_69a6591724e81\",\"items_2_title\":\"Association \\u0026 Nonprofit Course Development\",\"_items_2_title\":\"field_6977a41d78dd1\",\"items_2_image\":144,\"_items_2_image\":\"field_6977a42478dd2\",\"items_2_link\":\"\",\"_items_2_link\":\"field_6977a42d78dd3\",\"items_3_tag\":\"\",\"_items_3_tag\":\"field_69a6591724e81\",\"items_3_title\":\"Patient Education\",\"_items_3_title\":\"field_6977a41d78dd1\",\"items_3_image\":146,\"_items_3_image\":\"field_6977a42478dd2\",\"items_3_link\":\"\",\"_items_3_link\":\"field_6977a42d78dd3\",\"items_4_tag\":\"\",\"_items_4_tag\":\"field_69a6591724e81\",\"items_4_title\":\"Safety Training\",\"_items_4_title\":\"field_6977a41d78dd1\",\"items_4_image\":147,\"_items_4_image\":\"field_6977a42478dd2\",\"items_4_link\":\"\",\"_items_4_link\":\"field_6977a42d78dd3\",\"items_5_tag\":\"\",\"_items_5_tag\":\"field_69a6591724e81\",\"items_5_title\":\"Software Training\",\"_items_5_title\":\"field_6977a41d78dd1\",\"items_5_image\":148,\"_items_5_image\":\"field_6977a42478dd2\",\"items_5_link\":\"\",\"_items_5_link\":\"field_6977a42d78dd3\",\"items\":6,\"_items\":\"field_6977a40c78dd0\"},\"mode\":\"preview\"} /-->

