<!-- wp:acf/video-block {\"name\":\"acf/video-block\",\"data\":{\"right_to_left\":\"0\",\"_right_to_left\":\"field_69ac28bd57647\",\"design\":\"mesh\",\"_design\":\"field_69ac290257648\",\"title\":\"What is a Microlearning Video?\",\"_title\":\"field_6976d60a207b6\",\"content\":\"Microlearning solutions use video to combine hyper-focused content, stunning animation, and exciting audio to produce an eLearning method that works for every student. Slide decks are a thing of the past and just don?t offer the same benefits and desired outcome ? if they even finish it? at all!\\r\\n\\r\\nWith microlearning solutions, less is definitely more ? more engagement, more output? more RESULTS!\",\"_content\":\"field_6976d622207b7\",\"link\":{\"title\":\"Get in Touch\",\"url\":\"/contact-us/\",\"target\":\"\"},\"_link\":\"field_6976d62a207b8\",\"video\":\"https://vimeo.com/727563749?fl=pl\\u0026fe=sh\",\"_video\":\"field_6976d638207b9\",\"thumbnail\":\"\",\"_thumbnail\":\"field_697abd828e0bf\"},\"mode\":\"preview\"} /-->

