<!-- wp:acf/related-solutions {\"name\":\"acf/related-solutions\",\"data\":{\"title\":\"\\u003ch3\\u003eKey Benefits of \\u003cem\\u003eBranding\\u003c/em\\u003e Your Academy\\u003c/h3\\u003e\",\"_title\":\"field_69b76e87c539d\",\"solution_0_title\":\"\\u003ch4\\u003eEnhanced brand recognition:\\u003c/h4\\u003e\",\"_solution_0_title\":\"field_69b76ebbc539f\",\"solution_0_description\":\"A branded customer education program helps reinforce your company’s identity with a targeted user base.\\r\\n\\r\\n\\r\\n\",\"_solution_0_description\":\"field_69b76ecac53a0\",\"solution_0_image\":555,\"_solution_0_image\":\"field_69b76ed5c53a1\",\"solution_0_link\":\"\",\"_solution_0_link\":\"field_69b76edfc53a2\",\"solution_1_title\":\"\\u003ch4\\u003eImproved learner experience:\\u003c/h4\\u003e\",\"_solution_1_title\":\"field_69b76ebbc539f\",\"solution_1_description\":\"A consistent brand experience can make it easier for learners to navigate your academy and drive customer success.\\r\\n\\r\\n\",\"_solution_1_description\":\"field_69b76ecac53a0\",\"solution_1_image\":1091,\"_solution_1_image\":\"field_69b76ed5c53a1\",\"solution_1_link\":\"\",\"_solution_1_link\":\"field_69b76edfc53a2\",\"solution_2_title\":\"\\u003ch4\\u003eIncreased engagement:\\u003c/h4\\u003e\",\"_solution_2_title\":\"field_69b76ebbc539f\",\"solution_2_description\":\"A branded academy can help you build a stronger connection with your customers and increase production adoption.\",\"_solution_2_description\":\"field_69b76ecac53a0\",\"solution_2_image\":1092,\"_solution_2_image\":\"field_69b76ed5c53a1\",\"solution_2_link\":\"\",\"_solution_2_link\":\"field_69b76edfc53a2\",\"solution\":3,\"_solution\":\"field_69b76ea9c539e\"},\"mode\":\"preview\"} /-->

