<!-- wp:acf/section-2-rows {\"name\":\"acf/section-2-rows\",\"data\":{\"right_to_left\":\"1\",\"_right_to_left\":\"field_699a2bc7383f5\",\"design\":\"mesh\",\"_design\":\"field_699a2be0383f6\",\"title\":\"\\u003ch2\\u003e\\u003c/h2\\u003e\\r\\n\\u003ch2\\u003eEducate patients, market your services online and in office\\u003c/h2\\u003e\",\"_title\":\"field_69765f2c461c3\",\"description\":\"Our patient education videos go beyond traditional methods. We translate complex medical information into easily digestible visual stories. This not only improves patient understanding but also strengthens their trust in your practice. Whether it’s showcasing treatment options, explaining procedures, or promoting health literacy, our videos serve as powerful tools for both patient education and practice marketing\",\"_description\":\"field_69765f79461c4\",\"image\":\"\",\"_image\":\"field_699a2d9482a32\"},\"mode\":\"preview\"} /-->

