<!-- wp:acf/section-2-rows {\"name\":\"acf/section-2-rows\",\"data\":{\"right_to_left\":\"1\",\"_right_to_left\":\"field_699a2bc7383f5\",\"design\":\"gradient\",\"_design\":\"field_699a2be0383f6\",\"title\":\"\\u003ch2\\u003eTest Your Site for ADA Compliance With Fonts and Colors\\u003c/h2\\u003e\",\"_title\":\"field_69765f2c461c3\",\"description\":\"Are your website and educational tools accessible to those who are sight-challenged? Ninja Tropic’s Color Checker is a free tool that determines if your site is compliant with the Americans with Disabilities Act (ADA) and its regulations related to online materials. This tool determines the contrast ratio between your site’s foreground and background colors, and informs you if this contrast is compliant with ADA guidelines.\",\"_description\":\"field_69765f79461c4\",\"image\":\"\",\"_image\":\"field_699a2d9482a32\"},\"mode\":\"preview\"} /-->

